import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const r="/penn-notes/news/2026-08/8c3736c72748.jpg",o="/penn-notes/news/2026-08/402f27ceca13.jpg",i="/penn-notes/news/2026-08/d3750e5287f1.jpg",c="/penn-notes/news/2026-08/d8e99e146332.png",p="/penn-notes/news/2026-08/aca559e24ca0.jpg",l="/penn-notes/news/2026-08/36fc34a4aae5.png",h="/penn-notes/news/2026-08/96cd39d89f29.jpg",d="/penn-notes/news/2026-08/e65c9a26c5e1.png",g="/penn-notes/news/2026-08/0c5b475b3032.webp",m="/penn-notes/news/2026-08/453ee3cf23c1.png",I=JSON.parse('{"title":"AI 动态 · 2026-08-14","description":"","frontmatter":{"title":"AI 动态 · 2026-08-14","date":"2026-08-14T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-14.md","filePath":"news/2026-08/ai-news-2026-08-14.md","lastUpdated":1787416107000}'),u={name:"news/2026-08/ai-news-2026-08-14.md"};function w(k,e,b,f,_,A){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-08-14" tabindex="-1">AI 动态 · 2026-08-14 <a class="header-anchor" href="#ai-动态-·-2026-08-14" aria-label="Permalink to &quot;AI 动态 · 2026-08-14&quot;">​</a></h1><blockquote><p>截至 2026-08-14。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="databricks-完成-50-亿美元融资-估值达-1900-亿美元" tabindex="-1">Databricks 完成 50 亿美元融资，估值达 1900 亿美元 <a class="header-anchor" href="#databricks-完成-50-亿美元融资-估值达-1900-亿美元" aria-label="Permalink to &quot;Databricks 完成 50 亿美元融资，估值达 1900 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+r+'" alt="配图"></p><p>Databricks 最新一轮融资以 1900 亿美元估值募集 50 亿美元。CEO Ali Ghodsi 透露，公司原本计划融资 10 亿美元，但投资者需求高达 150 亿美元，最终超额完成。AI 高昂的算力成本是此次大规模融资的主要驱动力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/databricks-wanted-to-raise-1b-investors-wanted-15b-it-settled-on-5b-at-a-190b-valuation/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-一周内再失高管-首席营收官-denise-dresser-离职" tabindex="-1">OpenAI 一周内再失高管：首席营收官 Denise Dresser 离职 <a class="header-anchor" href="#openai-一周内再失高管-首席营收官-denise-dresser-离职" aria-label="Permalink to &quot;OpenAI 一周内再失高管：首席营收官 Denise Dresser 离职&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+o+'" alt="配图"></p><p>OpenAI 首席营收官 Denise Dresser 宣布将在未来几周内离职，这是该公司本周第二位离职的高管。此前，特别项目负责人 Brad Lightcap 也已宣布离开。Wiz 总裁兼 COO Dali Rajic 将接任 CRO 职位。连续高管出走引发外界对 OpenAI 内部稳定性的关注。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/979815/openai-denise-dresser-leaving-executive-departure" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-与-anthropic-陷入价格战-应对中国-ai-对手崛起" tabindex="-1">OpenAI 与 Anthropic 陷入价格战，应对中国 AI 对手崛起 <a class="header-anchor" href="#openai-与-anthropic-陷入价格战-应对中国-ai-对手崛起" aria-label="Permalink to &quot;OpenAI 与 Anthropic 陷入价格战，应对中国 AI 对手崛起&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+i+'" alt="配图"></p><p>面对中国 AI 竞争对手带来的新挑战，OpenAI 和 Anthropic 等美国公司纷纷发布更便宜的模型，开启价格战。此举旨在应对对其万亿美元市场目标的威胁，也反映出全球 AI 模型市场竞争格局的加剧与成本压力的传导。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/openai-and-anthropic-in-price-war-as-chinese-ai-rivals-gain-ground/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="anthropic-详解-claude-文本水印技术-为遵守欧盟-ai-法案" tabindex="-1">Anthropic 详解 Claude 文本水印技术：为遵守欧盟 AI 法案 <a class="header-anchor" href="#anthropic-详解-claude-文本水印技术-为遵守欧盟-ai-法案" aria-label="Permalink to &quot;Anthropic 详解 Claude 文本水印技术：为遵守欧盟 AI 法案&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Anthropic News</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+c+'" alt="配图"></p><p>Anthropic 宣布未来 Claude 模型生成的文本将包含水印，用于判断文本由 Claude 撰写的可能性。此举是为了遵守欧盟 AI 法案，该公司与其他几家主要 AI 提供商共同实施这一变更。文章回答了关于水印方法原理、是否影响输出质量以及变更原因等问题。</p><p class="news-entry-source"><a href="https://www.anthropic.com/news/claude-text-watermark" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="google-sheets-推出-canvas-功能-用提示词将数据变为交互式仪表盘" tabindex="-1">Google Sheets 推出 Canvas 功能：用提示词将数据变为交互式仪表盘 <a class="header-anchor" href="#google-sheets-推出-canvas-功能-用提示词将数据变为交互式仪表盘" aria-label="Permalink to &quot;Google Sheets 推出 Canvas 功能：用提示词将数据变为交互式仪表盘&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+p+'" alt="配图"></p><p>Google 在 Sheets 中推出 Canvas 功能，用户只需简单提示即可将数据转化为交互式仪表盘、自定义学习追踪器、座位表等迷你应用。该功能由 Gemini 驱动，旨在降低数据分析与可视化门槛，让非技术用户也能快速构建数据应用。</p><p class="news-entry-source"><a href="https://blog.google/products-and-platforms/products/workspace/sheets-canvas-for-google-sheets-spreadsheets/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-发布-gemini-3-7-flash-面向编码与-agent-的最强工作模型" tabindex="-1">Google 发布 Gemini 3.7 Flash：面向编码与 Agent 的最强工作模型 <a class="header-anchor" href="#google-发布-gemini-3-7-flash-面向编码与-agent-的最强工作模型" aria-label="Permalink to &quot;Google 发布 Gemini 3.7 Flash：面向编码与 Agent 的最强工作模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+l+'" alt="配图"></p><p>Google DeepMind 发布 Gemini 3.7 Flash，定位为面向编码和智能体任务的最强工作模型。该模型距上一版本仅三周，官方称有“实质性改进”。在 AI 领导层变动的背景下，此举被视为 Google 加速模型迭代、巩固市场地位的重要信号。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/introducing-gemini-3-7-flash/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="writer-发布基于-glm-5-2-的新模型与升级-harness-降低-token-成本" tabindex="-1">Writer 发布基于 GLM-5.2 的新模型与升级 Harness，降低 Token 成本 <a class="header-anchor" href="#writer-发布基于-glm-5-2-的新模型与升级-harness-降低-token-成本" aria-label="Permalink to &quot;Writer 发布基于 GLM-5.2 的新模型与升级 Harness，降低 Token 成本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+h+'" alt="配图"></p><p>Writer 推出新 AI 模型及升级版 Harness，该模型基于 Z.ai 的开源模型 GLM-5.2 进行后训练改造。官方表示新系统能以更低价格提供部署就绪的能力，旨在帮助企业控制 Token 成本，在保证性能的同时提升经济性。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/writer-introduces-new-ai-model-and-upgraded-harness-to-contain-token-costs/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="hugging-face-发布-2026-夏季开源模型观察报告" tabindex="-1">Hugging Face 发布 2026 夏季开源模型观察报告 <a class="header-anchor" href="#hugging-face-发布-2026-夏季开源模型观察报告" aria-label="Permalink to &quot;Hugging Face 发布 2026 夏季开源模型观察报告&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+d+'" alt="配图"></p><p>Hugging Face 发布《State of Open Models: Summer 2026 Observations》报告，对当前开源模型生态进行深入分析。报告指出“注意力不等于采用率”，并探讨了开放权重如何改变价值积累的位置，为理解开源 AI 的发展趋势提供了重要视角。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/state-of-open-models-summer-2026" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="深度求索开源-agent-框架-deepseek-harness-主打-一切皆插件" tabindex="-1">深度求索开源 Agent 框架 DeepSeek Harness，主打“一切皆插件” <a class="header-anchor" href="#深度求索开源-agent-框架-deepseek-harness-主打-一切皆插件" aria-label="Permalink to &quot;深度求索开源 Agent 框架 DeepSeek Harness，主打“一切皆插件”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+g+'" alt="配图"></p><p>深度求索正式推出开源 Agent 框架 DeepSeek Harness 开发者预览版，采用 MIT 许可证。该框架基于 Cordis 插件系统构建，设计理念为“一切皆插件”，模型、工具、Skills、会话、沙箱、存储等均可替换。同时发布 DeepSeek-V4-Pro GA 版本。开发者可通过 npx 快速启动 Web UI。</p><p class="news-entry-source"><a href="https://sspai.com/post/113434" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="css-tricks-周报-custom-highlight-api、css-导航匹配与-text-stroke-修复" tabindex="-1">CSS-Tricks 周报：Custom Highlight API、CSS 导航匹配与 text-stroke 修复 <a class="header-anchor" href="#css-tricks-周报-custom-highlight-api、css-导航匹配与-text-stroke-修复" aria-label="Permalink to &quot;CSS-Tricks 周报：Custom Highlight API、CSS 导航匹配与 text-stroke 修复&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="'+m+'" alt="配图"></p><p>本期 CSS-Tricks 周报汇总了多项前沿 CSS 技术，包括如何使用 CSS Custom Highlight API、CSS 导航匹配、修复 text-stroke 的问题，以及如何为骨架屏（Skeleton UI）添加样式、实现斜向滚动和图片自溢出的技巧，为前端开发者提供了丰富的实用参考。</p><p class="news-entry-source"><a href="https://css-tricks.com/whats-important-17/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const S=a(u,[["render",w]]);export{I as __pageData,S as default};
